#!/usr/bin/env python3
"""Trim oversized tool_result payloads out of a Claude Code transcript.

Structure-preserving: only rewrites the *text* inside existing tool_result
blocks. uuid / parentUuid / block ordering / tool_use pairing are untouched,
so the parentUuid chain the harness walks stays byte-for-byte valid.
"""
import json
import sys
import shutil
import os

PATH = "/home/ubuntu/.claude/projects/-home-ubuntu/1922c1ec-ec29-4fe4-a796-77c185b1f8e5.jsonl"
BACKUP = PATH + ".bak-before-trim"

TARGET_FREED = 250_000   # chars to free; we only need ~2k to clear the 614-token overage
KEEP_HEAD = 1_200        # chars of each tool_result kept for semantic signal
MIN_TRUNC = 4_000        # don't bother truncating anything smaller than this
TAIL_GUARD = 1_900       # never touch the last N lines (current working context)

MARK = "\n\n[... 已截断 {n} 字符以释放上下文；完整内容见 {b} ...]"


def truncate_str(s):
    """Return (new_string, freed_chars) or (None, 0) if not worth it."""
    if not isinstance(s, str) or len(s) <= MIN_TRUNC:
        return None, 0
    tail = MARK.format(n=len(s) - KEEP_HEAD, b=os.path.basename(BACKUP))
    return s[:KEEP_HEAD] + tail, len(s) - (KEEP_HEAD + len(tail))


def main():
    with open(PATH, encoding="utf-8") as fh:
        lines = fh.read().split("\n")

    # Candidate lines: parseable, old enough, carrying a tool_result payload.
    cands = []
    for idx, raw in enumerate(lines):
        if not raw.strip():
            continue
        if idx >= len(lines) - TAIL_GUARD:
            continue
        try:
            obj = json.loads(raw)
        except Exception:
            continue
        if obj.get("type") != "user":
            continue
        content = (obj.get("message") or {}).get("content")
        size = 0
        if isinstance(content, str):
            size += len(content)
        elif isinstance(content, list):
            for blk in content:
                if isinstance(blk, dict) and blk.get("type") == "tool_result":
                    sub = blk.get("content")
                    if isinstance(sub, str):
                        size += len(sub)
                    elif isinstance(sub, list):
                        size += sum(len(b.get("text", "")) for b in sub
                                    if isinstance(b, dict) and b.get("type") == "text")
        if size > MIN_TRUNC:
            cands.append((size, idx))

    cands.sort(reverse=True)
    print(f"candidates > {MIN_TRUNC} chars: {len(cands)}")
    print(f"total payload in candidates:  {sum(s for s, _ in cands):,} chars")

    freed = 0
    touched = []
    for size, idx in cands:
        if freed >= TARGET_FREED:
            break
        obj = json.loads(lines[idx])
        content = obj["message"]["content"]
        gained = 0

        if isinstance(content, str):
            new, g = truncate_str(content)
            if g:
                obj["message"]["content"] = new
                gained += g
        elif isinstance(content, list):
            for blk in content:
                if not (isinstance(blk, dict) and blk.get("type") == "tool_result"):
                    continue
                sub = blk.get("content")
                if isinstance(sub, str):
                    new, g = truncate_str(sub)
                    if g:
                        blk["content"] = new
                        gained += g
                elif isinstance(sub, list):
                    for b in sub:
                        if isinstance(b, dict) and b.get("type") == "text":
                            new, g = truncate_str(b.get("text", ""))
                            if g:
                                b["text"] = new
                                gained += g

        if gained:
            lines[idx] = json.dumps(obj, ensure_ascii=False, separators=(",", ":"))
            freed += gained
            touched.append((idx + 1, size, gained))

    if not touched:
        print("nothing to do")
        return 1

    tmp = PATH + ".tmp"
    with open(tmp, "w", encoding="utf-8") as fh:
        fh.write("\n".join(lines))
    shutil.copymode(PATH, tmp)
    os.replace(tmp, PATH)

    print(f"\ntruncated {len(touched)} tool_result payloads, freed {freed:,} chars")
    for ln, before, g in sorted(touched):
        print(f"  line {ln:>6}: {before:>7,} -> {before - g:>6,} chars  (freed {g:,})")
    return 0


if __name__ == "__main__":
    sys.exit(main())
